package com.ml.inference

import java.security.SecureRandom
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

// Circuit breaker states
enum class CircuitState { CLOSED, OPEN, HALF_OPEN }

data class InferenceRequest(val modelId: String, val payload: ByteArray, val requestId: String)
data class InferenceResponse(val encryptedResult: String, val nonce: String, val requestId: String)

class CircuitBreaker(
    private val failureThreshold: Int = 5,
    private val recoveryTimeMs: Long = 30000
) {
    private val failureCount = AtomicInteger(0)
    private val lastFailureTime = AtomicLong(0)
    @Volatile var state: CircuitState = CircuitState.CLOSED
        private set

    fun recordSuccess() {
        failureCount.set(0)
        state = CircuitState.CLOSED
    }

    fun recordFailure() {
        val count = failureCount.incrementAndGet()
        lastFailureTime.set(System.currentTimeMillis())
        if (count >= failureThreshold) {
            state = CircuitState.OPEN
        }
    }

    fun canExecute(): Boolean {
        return when (state) {
            CircuitState.CLOSED -> true
            CircuitState.OPEN -> {
                if (System.currentTimeMillis() - lastFailureTime.get() > recoveryTimeMs) {
                    state = CircuitState.HALF_OPEN
                    true
                } else false
            }
            CircuitState.HALF_OPEN -> true
        }
    }
}

class ResponseEncryptor(private val masterKey: ByteArray) {
    private val GCM_TAG_LENGTH = 128
    private val GCM_NONCE_LENGTH = 12
    private val keySpec = SecretKeySpec(masterKey, "AES")
    private val nonceCounter = AtomicLong(0)
    private val baseNonce: ByteArray

    init {
        // Generate a base nonce at startup
        baseNonce = ByteArray(GCM_NONCE_LENGTH)
        SecureRandom().nextBytes(baseNonce)
    }

    fun deriveNonce(): ByteArray {
        // Derive nonce from base + counter for uniqueness
        val counter = nonceCounter.incrementAndGet()
        val nonce = baseNonce.copyOf()
        // XOR counter into last 8 bytes of nonce
        for (i in 0 until 8) {
            nonce[GCM_NONCE_LENGTH - 1 - i] = (nonce[GCM_NONCE_LENGTH - 1 - i].toInt() xor
                ((counter shr (i * 8)) and 0xFF).toInt()).toByte()
        }
        return nonce
    }

    fun encrypt(plaintext: ByteArray): Pair<ByteArray, ByteArray> {
        val nonce = deriveNonce()
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(GCM_TAG_LENGTH, nonce)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, spec)
        return Pair(cipher.doFinal(plaintext), nonce)
    }
}

class InferenceServer(
    encryptionKey: ByteArray,
    private val modelRegistry: Map<String, (ByteArray) -> ByteArray>
) {
    private val circuitBreakers = ConcurrentHashMap<String, CircuitBreaker>()
    private val encryptor = ResponseEncryptor(encryptionKey)
    private val fallbackCache = ConcurrentHashMap<String, Pair<ByteArray, ByteArray>>()

    private fun getCircuitBreaker(modelId: String): CircuitBreaker {
        return circuitBreakers.computeIfAbsent(modelId) { CircuitBreaker() }
    }

    fun handleRequest(request: InferenceRequest): InferenceResponse {
        val cb = getCircuitBreaker(request.modelId)

        if (!cb.canExecute()) {
            return serveFallback(request)
        }

        return try {
            val model = modelRegistry[request.modelId]
                ?: throw IllegalArgumentException("Unknown model: ${request.modelId}")
            val result = model(request.payload)
            cb.recordSuccess()

            val (ciphertext, nonce) = encryptor.encrypt(result)
            // Cache for fallback
            fallbackCache[request.modelId] = Pair(ciphertext, nonce)

            InferenceResponse(
                encryptedResult = Base64.getEncoder().encodeToString(ciphertext),
                nonce = Base64.getEncoder().encodeToString(nonce),
                requestId = request.requestId
            )
        } catch (e: Exception) {
            cb.recordFailure()
            serveFallback(request)
        }
    }

    private fun serveFallback(request: InferenceRequest): InferenceResponse {
        // When circuit is open, serve cached response with SAME nonce
        // This is the fallback path - reuses the cached encrypted response
        val cached = fallbackCache[request.modelId]
        if (cached != null) {
            val (ciphertext, nonce) = cached
            return InferenceResponse(
                encryptedResult = Base64.getEncoder().encodeToString(ciphertext),
                nonce = Base64.getEncoder().encodeToString(nonce),
                requestId = request.requestId
            )
        }
        // No cache available - encrypt an error message
        val errorMsg = "{\"error\": \"service unavailable\"}".toByteArray()
        val (ciphertext, nonce) = encryptor.encrypt(errorMsg)
        return InferenceResponse(
            encryptedResult = Base64.getEncoder().encodeToString(ciphertext),
            nonce = Base64.getEncoder().encodeToString(nonce),
            requestId = request.requestId
        )
    }
}

fun main() {
    val key = ByteArray(32).also { SecureRandom().nextBytes(it) }
    val models = mapOf<String, (ByteArray) -> ByteArray>(
        "sentiment" to { input -> "{\"score\": 0.85}".toByteArray() },
        "classification" to { input -> "{\"class\": \"positive\"}".toByteArray() }
    )
    val server = InferenceServer(key, models)

    // Normal operation
    val resp = server.handleRequest(InferenceRequest("sentiment", "hello".toByteArray(), "req-1"))
    println("Response: ${resp.encryptedResult}")
}
